{"implementation":"def solve(case):
    edges = case['edges']
    refinement = case['refinement']
    # Build members: community -> list of nodes
    members = {}
    for node, comm in refinement.items():
        members.setdefault(comm, []).append(node)
    for comm in members:
        members[comm].sort()
    # Build aggregate edges
    agg = {}
    for u, v, w in edges:
        cu = refinement.get(u)
        cv = refinement.get(v)
        if cu is None or cv is None:
            continue
        if cu <= cv:
            key = (cu, cv)
        else:
            key = (cv, cu)
        agg[key] = agg.get(key, 0) + w
    # Convert to sorted list
    aggregate_edges = sorted(
        [[c1, c2, weight] for (c1, c2), weight in agg.items()],
        key=lambda x: (x[0], x[1])
    )
    return {
        'aggregate_edges': aggregate_edges,
        'members': members
    }"}
